<script setup lang="ts">
import { ui } from "../ui"
import DateTime from '../components/DateTime.vue'
import {computed,ref,onMounted,onUnmounted} from 'vue'
import PageHeading from '../components/PageHeading.vue'
import SetupDestinations from '../components/SetupDestinations.vue'
import SettingsForm from '../components/SettingsForm.vue'
import HealthTable from '../components/HealthTable.vue'
import OperationsPanel from '../components/OperationsPanel.vue'
import {api,bootstrap,notify,loadBootstrap} from '../composables/api'
import type {Check,CaptureProbe,SetupStatus} from '../types'
const probe=ref<CaptureProbe|null>(null),testing=ref(false),waiting=ref(false),status=ref<SetupStatus|null>(null),failure=ref(''),finishing=ref(false),selecting=ref(false)
let poll:ReturnType<typeof setTimeout>|undefined,disposed=false
onUnmounted(()=>{disposed=true;clearTimeout(poll)})
const probeMessage=computed(()=>{if(!probe.value)return 'The test uses the real Telescope and queue path. Notifications and external actions are suppressed.';return ({pending:'Waiting for a capture worker. Run the configured queue worker, then check again.',captured:'Telescope accepted the sample. Durable ingestion is waiting for a worker.',completed:'Capture verified. The sample has retained, sanitized evidence.',recording_disabled:'Recording or its exception watcher is disabled. Review host configuration before trying again.',filtered_or_unstored:'Telescope did not retain the sample. Review entry and batch filters.',cancelled:'The test was cancelled because access or the installation changed.',expired:'This capture check expired. Generate a new sample.'} as Record<string,string>)[probe.value.state]??'Review system health for the safe diagnostic.'})
async function loadStatus(){try{status.value=await api('/setup/status');failure.value=''}catch(e){failure.value=e instanceof Error?e.message:'Setup status unavailable.'}}
async function refresh(){await loadBootstrap();await loadStatus()}
onMounted(()=>{if(bootstrap.value?.features.operations&&bootstrap.value.capabilities.manage)loadStatus()})
async function readProbe(attempt=0){if(!probe.value||disposed)return;try{probe.value=await api<CaptureProbe>('/capture/probes/'+probe.value.id);waiting.value=['pending','captured'].includes(probe.value.state);if(waiting.value&&attempt<14)poll=setTimeout(()=>readProbe(attempt+1),2000);else{waiting.value=false;await refresh()}}catch(e){waiting.value=false;notify(e instanceof Error?e.message:'Capture status unavailable.',true)}}
async function testCapture(){clearTimeout(poll);testing.value=true;try{probe.value=await api('/capture/probes','POST',{client_key:crypto.randomUUID()});waiting.value=true;await readProbe()}catch(e){notify(e instanceof Error?e.message:'Capture check could not be queued.',true)}finally{testing.value=false}}
const steps=['Installation','Application','Privacy','Test capture','Alert destination','Test delivery','Operations','Finish'],headings=['Verify installation','Identify the application','Review retained evidence','Test exception capture','Choose an alert destination','Test notification delivery','Verify processing and maintenance','Review and finish']
const destinations=ref<InstanceType<typeof SetupDestinations>|null>(null),preferencesForm=ref<InstanceType<typeof SettingsForm>|null>(null),step=ref(Math.max(0,Math.min(7,bootstrap.value?.installation?.setup.current_step??0))),checking=ref(false),checks=ref<Check[]|null>(null)
const manage=computed(()=>bootstrap.value?.capabilities.manage&&bootstrap.value.storage==='ready')
function canLeave(){return (!destinations.value||destinations.value.confirmLeave())&&(!preferencesForm.value||preferencesForm.value.confirmLeave())}
async function select(index:number){if(index===step.value||selecting.value||!canLeave())return;selecting.value=true;try{const values:Record<string,unknown>={step:index};if(index>step.value&&[1,2,6].includes(step.value)){values.acknowledge=step.value===1?'application':step.value===2?'privacy':'operations';values.config_revision=bootstrap.value?.installation?.config_revision}await api('/setup','PATCH',values);step.value=index;await refresh()}catch(e){failure.value=e instanceof Error?e.message:'Setup position could not be saved. Your current draft is preserved.'}finally{selecting.value=false}}
async function notifications(choice:'skip'|'verify'){if(!canLeave())return;selecting.value=true;try{await api('/setup','PATCH',{step:6,notification_choice:choice});step.value=6;await refresh()}catch(e){failure.value=e instanceof Error?e.message:'Notification choice could not be saved.'}finally{selecting.value=false}}
async function check(){checking.value=true;try{checks.value=await api<Check[]>('/health/check','POST');await loadStatus();notify('Checks refreshed. Processing observations remain distinct from configuration.')}catch(e){failure.value=e instanceof Error?e.message:'Checks unavailable.'}finally{checking.value=false}}
async function finish(){finishing.value=true;try{status.value=await api('/setup/finish','POST');await loadBootstrap();notify('Monitoring setup completed. Optional steps remain visible.')}catch(e){failure.value=e instanceof Error?e.message:'Setup could not be completed. Review the required checks.'}finally{finishing.value=false}}
const requirementLabels:Record<string,string>={installation:'Installation and recording configuration',application:'Application preferences reviewed',privacy:'Privacy policy reviewed',capture:'Current-generation capture verified',notifications:'Notification test or explicit skip',operations:'Operations checklist reviewed'},requirementSteps:Record<string,number>={installation:0,application:1,privacy:2,capture:3,notifications:5,operations:6}
</script>
<template><PageHeading :class="ui('$all', '$PageHeading')" :title="status?.complete?'Monitoring setup':'Set up monitoring'" subtitle="Connect capture, choose evidence, then verify delivery."><span :class="ui('$all', '$span', 'badge')">{{status?.complete?'Completed':'Resumable setup'}}</span></PageHeading><div v-if="!manage" :class="ui('$all', '$div', 'notice neutral')">An administrator must complete monitoring setup.</div><div v-else-if="!bootstrap?.features.operations" :class="ui('$all', '$div', 'notice warning')">Publish and run the operations migration before completing setup.</div><template v-else><div v-if="failure" :class="ui('$all', '$div', 'notice danger')" role="alert">{{failure}}<button :class="ui('$all', '$button', 'button')" @click="refresh">Refresh current status</button></div><div :class="ui('$all', '$div', 'panel setup-panel')"><nav :class="ui('$all', '$nav', 'setup-steps')" aria-label="Setup steps"><button v-for="(name,index) in steps" :key="name" :class="ui('$all', '$button', ({active:step===index}))" :disabled="selecting" :aria-current="step===index?'step':undefined" @click="select(index)"><span :class="ui('$all', '$span', 'step-circle')">{{index+1}}</span><span :class="ui('$all', '$span')">{{name}}</span></button></nav><div :class="ui('$all', '$div', 'setup-content')"><div :class="ui('$all', '$div', 'section-heading')"><h2 :class="ui('$all', '$h2')">{{headings[step]}}</h2><small :class="ui('$all', '$small')">Step {{step+1}} of 8</small></div>
<section :class="ui('$all', '$section')" v-if="step===0"><HealthTable :class="ui('$all', '$HealthTable')" :checks="checks??bootstrap.health"/><div :class="ui('$all', '$div', 'form-actions')"><button :class="ui('$all', '$button', 'button')" :disabled="checking" @click="check">{{checking?'Checking…':'Run installation checks'}}</button><button :class="ui('$all', '$button', 'button primary')" :disabled="selecting" @click="select(1)">Continue</button></div></section>
<SettingsForm :class="ui('$all', '$SettingsForm')" v-else-if="step===1" ref="preferencesForm" group="general" setup @saved="select(2)"/>
<SettingsForm :class="ui('$all', '$SettingsForm')" v-else-if="step===2" ref="preferencesForm" group="privacy" setup @saved="select(3)"/>
<section :class="ui('$all', '$section')" v-else-if="step===3"><div :class="ui('$all', '$div', 'setup-task')"><h3 :class="ui('$all', '$h3')">Generate a safe example</h3><p :class="ui('$all', '$p')">A labeled synthetic exception verifies the real source and retained evidence. It cannot trigger automatic notifications or GitHub creation.</p><button :class="ui('$all', '$button', 'button primary')" :disabled="testing||waiting||!bootstrap.features.capture" @click="testCapture">{{testing?'Starting…':waiting?'Checking capture…':'Generate sample event'}}</button></div><div :class="ui('$all', '$div', 'notice neutral spacing')" role="status" aria-live="polite"><div :class="ui('$all', '$div')"><strong :class="ui('$all', '$strong')">{{probe?.state==='completed'||status?.requirements.capture?'Capture verified':'Capture check'}}</strong><p :class="ui('$all', '$p')">{{probeMessage}}</p><p :class="ui('$all', '$p')" v-if="probe&&!probe.asynchronous_queue">An asynchronous database or Redis queue is required; this check never runs inline in the monitored request.</p></div></div><div :class="ui('$all', '$div', 'form-actions')"><button :class="ui('$all', '$button', 'button')" @click="select(2)">Back</button><button v-if="probe&&!waiting" :class="ui('$all', '$button', 'button')" @click="readProbe()">Refresh test status</button><RouterLink to="/settings/health" :class="ui('$all', '$a', 'text-link')">System health</RouterLink><button :class="ui('$all', '$button', 'button primary')" :disabled="!status?.requirements.capture" @click="select(4)">Continue</button></div></section>
<section :class="ui('$all', '$section')" v-else-if="step===4||step===5"><SetupDestinations :class="ui('$all', '$SetupDestinations')" ref="destinations" :key="step" :testing="step===5" @saved="step===4&&select(5)" @verified="notifications('verify')" @skip="notifications('skip')"/><div v-if="step===5&&status?.delivery_verified" :class="ui('$all', '$div', 'notice neutral spacing')"><div :class="ui('$all', '$div')"><p :class="ui('$all', '$p')">A current enabled destination has a recorded transport-accepted test: {{status.delivery_destination}}.</p><RouterLink v-if="status.delivery_verified_id" :to="'/alerts/history/'+status.delivery_verified_id" :class="ui('$all', '$a', 'text-link')">Inspect the recorded check</RouterLink><button :class="ui('$all', '$button', 'button')" @click="notifications('verify')">Use recorded check and continue</button></div></div></section>
<section :class="ui('$all', '$section')" v-else-if="step===6"><OperationsPanel :class="ui('$all', '$OperationsPanel')" compact/><div :class="ui('$all', '$div', 'form-actions setup-operations-actions')"><button :class="ui('$all', '$button', 'button')" @click="select(5)">Back</button><button :class="ui('$all', '$button', 'button primary')" :disabled="selecting" @click="select(7)">I reviewed the operations checklist</button></div></section>
<section :class="ui('$all', '$section')" v-else><div v-if="status?.complete" :class="ui('$all', '$div', 'notice success')"><div :class="ui('$all', '$div')"><h3 :class="ui('$all', '$h3')">Monitoring setup completed</h3><p :class="ui('$all', '$p')">Recorded <DateTime :class="ui('$all', '$DateTime')" :value="status.completed_at"/>. Current observations and optional configuration remain available below.</p></div></div><p v-else :class="ui('$all', '$p', 'help')">Complete required reviews and checks. Optional notifications can be explicitly skipped; this does not manufacture delivery verification.</p><ul v-if="status" :class="ui('$all', '$ul', 'setup-completion-list')"><li :class="ui('$all', '$li')" v-for="(ready,key) in status.requirements" :key="key"><span :class="ui('$all', '$span')">{{requirementLabels[key]}}</span><span :class="ui('$all', '$span', 'badge', (ready?(key==='notifications'&&status.notification_choice==='skip'?'':'passed'):'warning'))" >{{!ready?'Needs attention':key==='notifications'&&status.notification_choice==='skip'?'Skipped':key==='capture'||key==='notifications'?'Verified':'Reviewed'}}</span><button :class="ui('$all', '$button', 'text-link')" @click="select(requirementSteps[key]??0)">Review</button></li></ul><p v-if="status?.notification_choice==='skip'" :class="ui('$all', '$p', 'notice neutral')">Notifications were explicitly skipped. Capture and investigation remain available; configure destinations and rules when ready.</p><p v-if="!status?.active_rules" :class="ui('$all', '$p', 'help')">Optional: no automatic alert rule is enabled. A successful destination test does not enable a rule.</p><p v-if="!status?.optional.assignments" :class="ui('$all', '$p', 'help')">Optional: assignments remain disabled until a host directory is configured.</p><p :class="ui('$all', '$p', 'help')">{{status?.note}}</p><div :class="ui('$all', '$div', 'form-actions')"><button v-if="!status?.complete" :class="ui('$all', '$button', 'button primary')" :disabled="finishing||!status?.can_finish" @click="finish">{{finishing?'Completing…':'Finish setup'}}</button><button :class="ui('$all', '$button', 'button')" @click="refresh">Refresh checklist</button><RouterLink to="/overview" :class="ui('$all', '$a', 'button')">Open overview</RouterLink></div></section>
</div></div></template></template>
